import React, { useState } from "react";
import { ReactMic } from "@cleandersonlobo/react-mic";

function App() {
  const [record, setRecord] = useState(false);

  const onStop = (recordedBlob) => {
    console.log("recordedBlob", recordedBlob);
    // Bạn có thể gửi recordedBlob.blob -> Streamlit qua window.parent.postMessage nếu cần
  };

  return (
    <div style={{ textAlign: "center", padding: "20px" }}>
      <h2>🎤 Ghi âm trực tiếp</h2>
      <ReactMic
        record={record}
        className="sound-wave"
        onStop={onStop}
        strokeColor="#000000"
        backgroundColor="#FF4081"
      />
      <br />
      <button onClick={() => setRecord(true)}>Bắt đầu</button>
      <button onClick={() => setRecord(false)}>Dừng</button>
    </div>
  );
}

export default App;